import {planningEstimate} from './lastplanner-productivity.mjs';
import {SUBCONTRATOS} from './subcontratos.mjs';
import {weekDays,putAssignment,scheduleCapacity,teamKey,comparableHistory} from './lastplanner-daily.mjs';
import {sumarDias} from './lastplanner-model.mjs';
import {sessionActor} from './lastplanner-session.mjs';
export function dailyPlanner(form,initial,{activities=[],attendance=[],apu=()=>null}={}){
 let rows=structuredClone(initial.schedule||[]),selected=form.elements.inicioPlan.value,visible=selected,editing=null,repeatId=null;
 let rateAt=initial.estimateReference?.at||new Date().toISOString();
 let autoEstimate=null;
 let historical=initial.estimateReference?.status==='observado'?structuredClone(initial.estimateReference):null;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const host=document.createElement('section');host.className='lpDaily';const step=form.querySelector('[data-step="2"]'),advanced=step.querySelector('details');advanced.hidden=true;step.insertBefore(host,advanced);form.elements.dotacion.closest('label').hidden=true;
 const rateLabel=form.elements.rendimientoPlan.closest('label');host.innerHTML='<h4>Personal programado</h4><div data-week-nav></div><div class="lpDays" data-days></div><div data-day-editor></div><div data-simple-rate hidden></div><p data-daily-capacity role="status"></p><button type="button" data-trim hidden>Quitar asignaciones fuera del período</button><p data-schedule-warnings role="status" hidden></p>';
 host.querySelector('[data-simple-rate]').append(rateLabel);const source=form.querySelector('[data-rate-source]');if(!initial.source||/^\d+$/.test(initial.source))source.value='Estimación provisional del supervisor';
 const references=activities.flatMap(a=>a.planificacion?.schedule||[]),teams=[...new Map([...references,...rows].map(r=>[r.teamId,r])).values()];
 const value=n=>form.elements[n].value;
 const workName=()=>apu()?.operation?.label||apu()?.description||form.querySelector('[data-part-name]').value.trim()||value('actividad').trim();
 const reference=()=>{if(historical?.criteria&&(historical.criteria.partida!==workName()||historical.criteria.unit!==value('unidad')||historical.criteria.contractor!==value('contratista')||JSON.stringify([...(historical.criteria.teams||[])].sort())!==JSON.stringify([...new Set(rows.map(r=>r.teamName))].sort())))historical=null;return ({...(historical||{}),rate:Number(value('rendimientoPlan')),unit:form.querySelector('[data-rate-unit]').value,basis:form.querySelector('[data-rate-basis]').value,crew:form.querySelector('[data-crew]').value.split('\n').filter(Boolean).map(v=>({role:v.split(':')[0],count:Number(v.split(':')[1])})),source:historical?.source||'Estimación provisional del supervisor',notes:form.querySelector('[data-rate-notes]').value,status:historical?'observado':'provisional',actor:sessionActor()?.id,at:rateAt});};
 const leave=()=>!host.querySelector('[data-apply-assignment]')||confirm('Hay un equipo sin aplicar. ¿Descartar únicamente esta edición?');
 const changed=()=>form.dispatchEvent(new Event('input',{bubbles:true}));
 function refresh(){if(!value('inicioPlan')||!value('finPlan'))return;if(visible<weekDays(value('inicioPlan'))[0]||visible>weekDays(value('finPlan'))[6])visible=value('inicioPlan');const days=weekDays(visible);if(!days.includes(selected))selected=days.find(d=>d>=value('inicioPlan')&&d<=value('finPlan'))||days[0];
 host.querySelector('[data-week-nav]').innerHTML=`<button type="button" data-prev ${days[0]<=weekDays(value('inicioPlan'))[0]?'disabled':''}>← Semana anterior</button><button type="button" data-next ${days[6]>=weekDays(value('finPlan'))[6]?'disabled':''}>Semana siguiente →</button>`;
 host.querySelector('[data-prev]').onclick=()=>{if(!leave())return;visible=sumarDias(days[0],-7);refresh();};host.querySelector('[data-next]').onclick=()=>{if(!leave())return;visible=sumarDias(days[0],7);refresh();};
 host.querySelector('[data-days]').innerHTML=days.map((date,i)=>`<button type="button" data-date="${date}" aria-pressed="${date===selected}" ${date<value('inicioPlan')||date>value('finPlan')?'disabled title="Fuera del período"':''}>${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'][i]}<b>${Number(date.slice(-2))}</b><small>${rows.filter(r=>r.date===date).reduce((n,r)=>n+r.people,0)} pers.</small></button>`).join('');host.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{if(!leave())return;selected=b.dataset.date;editing=null;refresh();});renderDay();summarize();}
 const dateLabel=date=>new Intl.DateTimeFormat('es-CL',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));
 function renderDay(){
  const el=host.querySelector('[data-day-editor]'),today=rows.filter(r=>r.date===selected);
  el.innerHTML=`<h4>${esc(dateLabel(selected))}</h4>${today.map(r=>`<article class="lpScheduledTeam"><b>${esc(r.teamName)}</b><small>${esc(r.contractor)} · ${r.people} personas · ${r.hours!=null?r.hours+' h/persona':r.fraction+' jornada'}</small><div><button type="button" data-edit="${esc(r.id)}">Editar</button><button type="button" data-repeat-team="${esc(r.id)}" aria-expanded="${repeatId===r.id}">Repetir en otros días</button><button type="button" data-remove="${esc(r.id)}">Quitar</button></div></article>`).join('')||'<p>Sin personal programado.</p>'}<div data-team-repeat></div><button type="button" data-add ${selected<value('inicioPlan')||selected>value('finPlan')?'disabled':''}>Agregar equipo</button><div data-assignment></div>`;
  el.querySelector('[data-add]').onclick=()=>edit(null);el.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.edit)));el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(!leave())return;rows=rows.filter(r=>r.id!==b.dataset.remove);repeatId=null;refresh();changed();});
  el.querySelectorAll('[data-repeat-team]').forEach(b=>b.onclick=()=>{if(!leave())return;repeatId=repeatId===b.dataset.repeatTeam?null:b.dataset.repeatTeam;renderDay();});
  const source=today.find(r=>r.id===repeatId);if(!source){repeatId=null;return;}
  const panel=el.querySelector('[data-team-repeat]'),destinations=weekDays(visible).filter(d=>d>=value('inicioPlan')&&d<=value('finPlan')&&d!==selected);
  panel.innerHTML=`<h4>Repetir ${esc(source.teamName)}</h4><p>${esc(source.contractor)} · ${source.people} personas · ${source.hours!=null?source.hours+' h/persona':source.fraction+' jornada'}</p><fieldset><legend>¿Qué días trabajará este equipo?</legend><div class="lpRepeatDays">${destinations.map(d=>`<label><input type="checkbox" data-repeat-date="${d}"><span>${esc(dateLabel(d))}</span></label>`).join('')}</div></fieldset><p role="alert"></p><div class="lpRepeatActions"><button type="button" data-repeat class="primary">Aplicar a días marcados</button><button type="button" data-copy ${destinations.includes(sumarDias(selected,1))?'':'disabled'}>Solo al día siguiente</button><button type="button" data-all>Seleccionar toda la semana</button><button type="button" data-cancel-repeat>Cancelar</button></div>`;
  const copy=dates=>{const valid=[...new Set(dates)].filter(d=>destinations.includes(d));if(!valid.length){panel.querySelector('[role=alert]').textContent='Selecciona al menos un día para repetir este equipo.';return;}if(valid.some(d=>rows.some(r=>r.date===d&&r.teamId===source.teamId))&&!confirm('Este equipo ya tiene asignaciones en algunos días elegidos. ¿Actualizarlas? Los demás equipos se conservan.'))return;let next=rows;for(const date of valid)next=putAssignment(next,{...source,date});rows=next;repeatId=null;refresh();changed();};
  panel.querySelector('[data-copy]').onclick=()=>copy([sumarDias(selected,1)]);panel.querySelector('[data-repeat]').onclick=()=>copy([...panel.querySelectorAll('[data-repeat-date]:checked')].map(x=>x.dataset.repeatDate));panel.querySelector('[data-all]').onclick=()=>panel.querySelectorAll('[data-repeat-date]').forEach(x=>x.checked=true);panel.querySelector('[data-cancel-repeat]').onclick=()=>{repeatId=null;renderDay();};
 }

 function edit(row){if(!leave())return;repeatId=null;host.querySelector('[data-team-repeat]').replaceChildren();host.querySelectorAll('[data-repeat-team]').forEach(b=>b.setAttribute('aria-expanded','false'));editing=row?.id;const el=host.querySelector('[data-assignment]');el.innerHTML=`<label>Subcontratista<select data-company>${[...new Set([...SUBCONTRATOS.map(s=>s.nombre),...teams.map(t=>t.contractor),row?.contractor,value('contratista')].filter(Boolean))].map(c=>`<option ${c===(row?.contractor||value('contratista'))?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Equipo<input data-team list="lpTeams" value="${esc(row?.teamName||'')}"></label><datalist id="lpTeams">${[...new Map([...teams,...rows].map(t=>[t.teamId,t])).values()].map(t=>`<option value="${esc(t.teamName)}">${esc(t.contractor)}</option>`).join('')}</datalist><label>Personas previstas<input data-people type="number" min="1" step="1" value="${row?.people||''}"></label><label>Jornada<select data-fraction>${[[1,'Completa'],[.5,'Media'],[.25,'Un cuarto']].map(([v,label])=>`<option value="${v}" ${v===(row?.fraction||1)?'selected':''}>${label}</option>`).join('')}</select></label><details><summary>Horas de la jornada (opcional)</summary><label>Horas por persona<input type="number" min="0" max="24" step="any" data-hours-assigned value="${row?.hours||''}"></label><label>Horas de una jornada de referencia<input type="number" min="0" max="24" step="any" data-reference-hours value="${row?.referenceHours||''}"></label></details><p role="alert"></p><button type="button" data-apply-assignment>Aplicar equipo</button><button type="button" data-cancel-assignment>Cancelar</button>`;
 el.querySelector('[data-cancel-assignment]').onclick=()=>{editing=null;el.replaceChildren();};el.querySelector('[data-apply-assignment]').onclick=()=>{try{const get=k=>el.querySelector('[data-'+k+']').value;const next={...row,date:selected,contractor:get('company'),teamName:get('team').trim(),people:Number(get('people')),fraction:Number(get('fraction')),hours:get('hours-assigned')?Number(get('hours-assigned')):null,referenceHours:get('reference-hours')?Number(get('reference-hours')):null,specialty:value('especialidad'),responsible:value('responsable')};if(next.hours!=null&&(!(next.hours>0)||next.hours>24||!(next.referenceHours>0)||next.referenceHours>24))throw Error('Indica horas válidas y la duración de referencia.');const id=selected+'|'+teamKey(next.contractor,next.teamName);if(rows.some(r=>r.id===id&&r.id!==editing)&&!confirm('Este equipo ya está programado. ¿Actualizar su asignación?'))return;rows=putAssignment(rows.filter(r=>r.id!==editing),next);editing=null;refresh();changed();}catch(e){el.querySelector('[role=alert]').textContent=e.message;}};}
 function summarize(){
  const relevant=rows.filter(r=>r.date>=value('inicioPlan')&&r.date<=value('finPlan')),quantity=Number(value('cantidad')),outside=rows.length!==relevant.length;
  const conflicts=relevant.filter(r=>references.some(other=>other.id===r.id));
  autoEstimate=quantity>0?planningEstimate({apu:apu(),activities,attendance,criteria:{partida:workName(),unit:value('unidad'),contractor:value('contratista'),conditions:form.querySelector('[data-rate-notes]').value,teams:[...new Set(relevant.map(r=>r.teamName))]},rows:relevant,unit:value('unidad'),quantity}):null;
  const resourceLabel=autoEstimate?{'persona-dia':'jornadas-persona','persona-hora':'horas-persona','cuadrilla-dia':'jornadas-cuadrilla','cuadrilla-hora':'horas-cuadrilla'}[autoEstimate.reference.basis]:'';
  const text=autoEstimate?`Capacidad estimada${autoEstimate.capacity.unknown?' parcial':''}: ${autoEstimate.capacity.production.toLocaleString('es-CL')} ${value('unidad')}. Compromiso: ${quantity} ${value('unidad')}.${autoEstimate.difference<0?' La dotación programada podría ser insuficiente: faltan aproximadamente '+autoEstimate.missing.toLocaleString('es-CL',{maximumFractionDigits:1})+' '+resourceLabel+'.':autoEstimate.completionDate?' Término estimado según la programación: '+autoEstimate.completionDate+'.':''}`:'';
  const capacity=host.querySelector('[data-daily-capacity]');capacity.hidden=!autoEstimate;capacity.textContent=text;
  const warnings=host.querySelector('[data-schedule-warnings]');warnings.hidden=!outside&&!conflicts.length;warnings.textContent=[outside?'Hay asignaciones fuera del período: ajusta las fechas o elimínalas antes de guardar.':'',conflicts.length?'Posible coincidencia de equipo y fecha con otra actividad: verifica los horarios.':''].filter(Boolean).join(' ');
  const trim=host.querySelector('[data-trim]');trim.hidden=!outside;trim.onclick=()=>{if(leave()&&confirm('¿Quitar únicamente las asignaciones fuera del nuevo período?')){rows=relevant;refresh();changed();}};
  const review=form.querySelectorAll('.lpWizardReview')[2];if(review){let box=review.querySelector('[data-schedule-review]');if(!box){box=document.createElement('div');box.dataset.scheduleReview='';review.append(box);}box.textContent=text;const list=document.createElement('details');list.innerHTML='<summary>Ver personal por día y equipo</summary>'+relevant.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(r=>'<p>'+esc(r.date+' · '+r.contractor+' · '+r.teamName+': '+r.people+' personas · '+(r.hours!=null?r.hours+' h/persona':r.fraction+' jornada'))+'</p>').join('');box.append(list);}
 }

 form.addEventListener('input',e=>{if(e.target.matches?.('[name=rendimientoPlan],[name=unidad],[name=contratista],[data-rate-basis],[data-rate-unit],[data-rate-notes],[data-part-name]'))historical=null;if(e.target.name==='rendimientoPlan'||e.target.matches('[data-rate-basis],[data-rate-unit],[data-rate-notes]'))rateAt=new Date().toISOString();if(['inicioPlan','finPlan'].includes(e.target.name)&&!host.querySelector('[data-apply-assignment]'))refresh();else summarize();});form.addEventListener('change',summarize);form.addEventListener('click',()=>queueMicrotask(summarize));refresh();
 return {read:()=>({schedule:structuredClone(rows),estimateReference:autoEstimate?.reference||initial.estimateReference||{...reference(),rate:null,status:'unavailable'}}),pending:()=>!!host.querySelector('[data-apply-assignment]')};
}
